import React, { useState } from 'react';
import { validateAndUseKey } from '../utils/data';

const AccessGate = ({ onPassed }) => {
  const [key, setKey] = useState('');
  const [error, setError] = useState(null);

  const handle = (e) => {
    e.preventDefault();
    const res = validateAndUseKey(key);
    if (res.valid) {
      sessionStorage.setItem('access_granted', '1');
      onPassed(res.role);
    } else {
      setError(res.reason || 'Key inválida');
    }
  };

  return (
    <main style={{ padding: '2rem', textAlign: 'center' }}>
      <h1 className="neon">/dev/terminal-forum — Access Gate</h1>
      <p>Introduce la clave de acceso para entrar</p>
      <form onSubmit={handle} style={{ maxWidth: 420, margin: '0 auto' }}>
        <input value={key} onChange={(e)=>setKey(e.target.value)} placeholder="Clave privada" />
        <button type="submit">Entrar</button>
        {error && <div style={{ color: 'red' }}>{error}</div>}
      </form>
    </main>
  );
};

export default AccessGate;
